export const whereWeBelongId = (number: StoryLessonNumber) => `conversational-skills-L4-C5-${number}-${whereWeBelongEpisodes[number].skill}-ja-v1`;
export function buildWhereWeBelongLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildNewBeginningLesson(number, previous, 'https://api.fluentxverse.com', reference, {
    episode: whereWeBelongEpisodes[number], id: whereWeBelongId(number), chapterName: 'Where We Belong',
    setting: 'Kamo House, the Kamo River and the fictional Riverbend Bakery in Kyoto; a Seoul hotel and client office; Nao\'s family home in Fukuoka.',
    previousSummary: index === 0 ? 'Kamo Collective handled the rain-day market successfully. Leo has only discussed evening kitchen rental. Nao has gallery opportunities; a Fukuoka visit was an unbooked idea. Emma and Ren are dating and shortlisted for a Seoul project, but no award, brief or travel was confirmed yet.' : whereWeBelongEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: 'The user\'s final chapter, Where We Belong, concludes the Kamo House story. Reference episodes1-4 and5-8 map to lesson slots1-4 and6-9. Level4 ends at Chapter5; slots5/10 remain dynamic student checkpoints. Keep speaking/listening/reading/speaking then speaking/speaking/reading/speaking, direct character roles, short tutor-first dialogues, concise private listening, fresh visible reading evidence, Japanese support, six vocabulary items, discussion/basic pronunciation, standard guides and actual-error tracking. No new images or physical-intimacy scenes. Track shortlisted then awarded then accepted temporary assignment; bakery planned then fitted out then opened. The hotel issue is resolved with a second room nearby, not a room-sharing scene. Budget figures are fictional teaching evidence, not financial advice. End full-circle with a newcomer, not a promise of Chapter6.',
  });
  lesson.storyData.characters = [
    { id: 'emma', name: 'Emma', role: 'main', description: 'Designer who completes a temporary Seoul assignment with Ren, returns to Japan and recognises her own growth while welcoming a new Kamo House resident.' },
    { id: 'ren', name: 'Ren', role: 'supporting', description: 'Emma\'s partner and design colleague. Handles technical delivery, shares practical preparation and returns from Seoul to his Japan-based role.' },
    { id: 'leo', name: 'Leo', role: 'supporting', description: 'Baker dating Nao. Meets her family, checks a shop budget carefully, and opens Riverbend Bakery after preparation, with support from his friends.' },
    { id: 'nao', name: 'Nao', role: 'supporting', description: 'Ceramic artist who welcomes Leo into her family, receives a Fukuoka gallery invitation, supports his business planning and continues her own artistic work.' },
    { id: 'claire', name: 'Claire', role: 'supporting', description: 'Kamo House organiser who negotiates a limited creative partnership, protects the cafe\'s welcoming identity and brings old and new friends together.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 4, chapter: 5, lessonNumber: number, levelBadge: 'BEGINNER', chapterLabel: 'Chapter 5: Where We Belong', status: previous?.status || 'draft', overlayColor: '#17252bcc', supportLanguage: 'ja' };
}
export function buildWhereWeBelongChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildWhereWeBelongLesson(number, {}, reference));
}
